package sohal.lld.chess.entity.board;import sohal.lld.chess.entity.playable.Piece;public class Cell {    final int row;    final int col;    Piece piece;    Cell(int row, int col) {        this.row = row;        this.col = col;    }    public boolean isOccupied() {        return piece != null;    }    public Piece getPiece() {        return piece;    }    public void setPiece(Piece piece) {        this.piece = piece;    }    public int getRow() {        return row;    }    public int getCol() {        return col;    }}